// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

describe('listing sessions', () => {
  const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

  beforeEach(() => {
    logLines.length = 0;
    const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
      void logLines.push({level, category, message, fields});
    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
  });

  afterEach(() => {
    setLogger();
  });

  const listHarness = (sessionStore?: SessionStore) => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler(orchestrator, sessionStore);
    return {sent, send: (raw: unknown) => handle(ws, session, raw)};
  };

  it('answers list_sessions with session_list using session.userId and ISO timestamps, forwarding limit and before', async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store = {
      listFor: (userId: string | number, options?: SessionListOptions) => {
        seen.push({userId, options});
        return summaries;
      },
    } as unknown as SessionStore;
    const h = listHarness(store);
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    await h.send({type: 'list_sessions', limit: 10, before});

    expect({seen, sent: h.sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when no sessionStore or listFor is provided', async () => {
    const noStore = listHarness();
    const noListFor = listHarness({} as SessionStore);

    await noStore.send({type: 'list_sessions'});
    await noListFor.send({type: 'list_sessions'});

    expect({noStore: noStore.sent, noListFor: noListFor.sent}).toEqual({
      noStore: [{type: 'session_list', sessions: []}],
      noListFor: [{type: 'session_list', sessions: []}],
    });
  });

  it('logs under ws and sends SERVER_ERROR when listFor rejects or throws', async () => {
    const errorStore = listHarness({
      listFor: () => Promise.reject(new Error('database offline')),
    } as unknown as SessionStore);
    const nonErrorStore = listHarness({
      listFor: () => Promise.reject('store unavailable'),
    } as unknown as SessionStore);

    await errorStore.send({type: 'list_sessions'});
    await nonErrorStore.send({type: 'list_sessions'});

    expect({
      frames: [...errorStore.sent, ...nonErrorStore.sent].map(frame => ({
        type: frame.type,
        code: frame.type === 'error' ? frame.code : undefined,
      })),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      frames: [
        {type: 'error', code: 'SERVER_ERROR'},
        {type: 'error', code: 'SERVER_ERROR'},
      ],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'store unavailable'}),
        },
      ],
    });
  });

  it('answers list_sessions at once while a user_message run is pending', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {
      readyState: WebSocket.OPEN as number,
      send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
    } as unknown as WebSocket;
    const gate = deferred();
    const processMessageStream = async function* (): AsyncGenerator<MessageChunk> {
      yield text('answer');
      await gate.until;
      yield STOP;
    };
    const store = {listFor: () => []} as unknown as SessionStore;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator, store);

    const run = handle(ws, session, userMessage('A'));
    await afterPendingWork();
    void handle(ws, session, {type: 'list_sessions'});
    await afterPendingWork();
    const beforeTheRunEnds = wire(sent);
    gate.release();
    await run;

    expect(beforeTheRunEnds).toEqual(['upsert 0 user "A"', 'upsert 1 assistant ""', 'delta 1 "answer"', 'session_list']);
  });
});

